use std::any::Any;
use std::panic::{AssertUnwindSafe, catch_unwind};

use crate::error::Error;
use crate::response::Response;

/// Executes a request handler and turns an unplanned panic into a `500`.
///
/// This is used by the code generated by `#[http_cgi::main]`. It is the single
/// place where panics are caught: expected failures are reported through
/// `Result` and never reach this guard.
///
/// The process serves exactly one request before exiting, so nothing can
/// observe partially mutated state; this is why `AssertUnwindSafe` is sound
/// here.
///
/// A panic is still reported by the default panic hook on stderr (the CGI
/// error log) before the generic `500` response is returned.
pub fn catch<F>(handler: F) -> Response
where
    F: FnOnce() -> Response,
{
    match catch_unwind(AssertUnwindSafe(handler)) {
        Ok(response) => response,
        Err(payload) => {
            log_panic(payload.as_ref());
            Error::Internal.into_response()
        }
    }
}

fn log_panic(payload: &(dyn Any + Send)) {
    let message = payload
        .downcast_ref::<&str>()
        .copied()
        .or_else(|| payload.downcast_ref::<String>().map(String::as_str))
        .unwrap_or("unknown panic payload");
    eprintln!("http-cgi: handler panicked: {message}");
}

#[cfg(test)]
mod tests {
    #![allow(
        clippy::unwrap_used,
        clippy::expect_used,
        clippy::panic,
        clippy::todo,
        clippy::unreachable,
        clippy::unimplemented
    )]

    use http::StatusCode;

    use super::*;
    use crate::response::IntoResponse;

    #[test]
    fn catch_converts_panics_to_a_generic_error() {
        // Keep the expected panic message out of the test output. The hook is
        // restored before any assertion so a real failure still reports.
        let previous = std::panic::take_hook();
        std::panic::set_hook(Box::new(|_| {}));

        let from_str = catch(|| panic!("boom"));
        let from_string = catch(|| std::panic::panic_any(String::from("boom")));
        let from_success = catch(|| (StatusCode::CREATED, "ok").into_response());

        std::panic::set_hook(previous);

        for response in [&from_str, &from_string] {
            assert_eq!(response.status(), StatusCode::INTERNAL_SERVER_ERROR);
            assert_eq!(response.body().as_ref(), b"Internal Server Error");
        }

        assert_eq!(from_success.status(), StatusCode::CREATED);
        assert_eq!(from_success.body().as_ref(), b"ok");
    }
}
